import math
import base64
from PySide6.QtCore import Qt, QTimer, QRect
from PySide6.QtGui import QPainter, QColor, QBrush, QPen, QLinearGradient, QPixmap, QFont
from PySide6.QtWidgets import QWidget

CHAR_BASE64 = ""

class AnimatedLoadingWidget(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.progress_val = 0.0
        self.target_progress = 0.0
        self.anim_tick = 0
        self.char_pixmap = None
        self.setFixedHeight(140)
        try:
            raw = base64.b64decode(CHAR_BASE64)
            pix = QPixmap()
            if pix.loadFromData(raw):
                self.char_pixmap = pix
        except Exception:
            pass
        self.timer = QTimer(self)
        self.timer.timeout.connect(self._on_tick)
        self.timer.start(35)

    def set_progress(self, val):
        self.target_progress = float(max(0, min(100, val)))

    def _on_tick(self):
        self.anim_tick += 1
        diff = self.target_progress - self.progress_val
        if abs(diff) > 0.3:
            self.progress_val += diff * 0.12
        else:
            self.progress_val = self.target_progress
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.setRenderHint(QPainter.SmoothPixmapTransform)
        w = self.width()
        h = self.height()
        bar_margin = 25
        bar_x = bar_margin
        bar_y = h - 45
        bar_w = max(10, w - (bar_margin * 2))
        bar_h = 16
        bg_pen = QPen(QColor("#78350f"), 2.2)
        painter.setPen(bg_pen)
        painter.setBrush(QBrush(QColor("#fef3c7")))
        painter.drawRoundedRect(bar_x, bar_y, bar_w, bar_h, 8, 8)
        fill_w = int(bar_w * (self.progress_val / 100.0))
        if fill_w > 6:
            painter.setPen(Qt.NoPen)
            grad = QLinearGradient(bar_x, bar_y, bar_x + fill_w, bar_y)
            grad.setColorAt(0.0, QColor("#fbbf24"))
            grad.setColorAt(1.0, QColor("#f59e0b"))
            painter.setBrush(QBrush(grad))
            painter.drawRoundedRect(bar_x + 2, bar_y + 2, fill_w - 4, bar_h - 4, 6, 6)
        if self.char_pixmap and not self.char_pixmap.isNull():
            bounce_y = int(math.sin(self.anim_tick * 0.38) * 6)
            char_w = 68
            char_h = 84
            scaled_char = self.char_pixmap.scaled(char_w, char_h, Qt.KeepAspectRatio, Qt.SmoothTransformation)
            char_x = int(bar_x + (bar_w - char_w) * (self.progress_val / 100.0))
            char_y = bar_y - char_h + 10 + bounce_y
            painter.drawPixmap(char_x, char_y, scaled_char)
        dots_count = (self.anim_tick // 8) % 4
        dots = "." * (dots_count + 1)
        loading_text = "Loading" + dots
        painter.setPen(QColor("#78350f"))
        font = QFont("Segoe UI", 11, QFont.Bold)
        painter.setFont(font)
        painter.drawText(QRect(0, h - 26, w, 24), Qt.AlignCenter, loading_text)
